// ---- lib/decision-maker.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Decision-maker identification.
// Small businesses: the founder/owner is the buyer. Larger ones: the person who
// owns the support queue is. The ranking below encodes that, and every choice
// carries a reason string that goes straight into the outreach prompt.
// ---------------------------------------------------------------------------

const ROLE_PATTERNS = [
  { role: 'founder',            re: /\b(founder|co[-\s]?founder|founding partner)\b/i },
  { role: 'owner',              re: /\b(owner|proprietor|principal|practice owner)\b/i },
  { role: 'ceo',                re: /\b(chief executive|ceo|managing director|president)\b/i },
  { role: 'head_of_operations', re: /\b(head of (operations|ops)|operations (director|manager|lead)|coo|director of operations)\b/i },
  { role: 'cx_director',        re: /\b(customer experience|cx (director|lead|manager)|head of customer)\b/i },
  { role: 'support_manager',    re: /\b(customer (support|service)|support (manager|lead)|service manager|patient coordinator|front office manager)\b/i },
  { role: 'marketing_director', re: /\b(marketing (director|manager|lead|head)|cmo|growth (lead|manager))\b/i }
];

/** Priority by company size. Index 0 is the strongest target. */
const PRIORITY_SMALL = ['founder', 'owner', 'co_founder', 'ceo', 'head_of_operations', 'support_manager', 'cx_director', 'marketing_director'];
const PRIORITY_LARGE = ['head_of_operations', 'cx_director', 'support_manager', 'marketing_director', 'ceo', 'founder', 'owner', 'co_founder'];

/** Fewer than this many employees counts as "small" for targeting purposes. */
const SMALL_COMPANY_MAX_EMPLOYEES = 25;

function classifyRole(title) {
  if (!title) return 'unknown';
  const t = String(title);
  if (/\bco[-\s]?founder\b/i.test(t)) return 'co_founder';
  for (const { role, re } of ROLE_PATTERNS) if (re.test(t)) return role;
  return 'other';
}

function isSmallBusiness({ employee_count = null, company_size = null, ig_followers = null, business_model = null } = {}) {
  if (typeof employee_count === 'number') return employee_count <= SMALL_COMPANY_MAX_EMPLOYEES;
  if (company_size) {
    const m = String(company_size).match(/(\d+)/);
    if (m) return Number(m[1]) <= SMALL_COMPANY_MAX_EMPLOYEES;
    if (/^(1-10|11-20|11-50|small|micro)$/i.test(company_size)) return true;
  }
  // No size signal: an account in our follower band is almost always small.
  if (ig_followers != null && ig_followers <= 25000) return true;
  return business_model === 'local_service';
}

function contactCompleteness(contact) {
  let n = 0;
  if (contact.email) n += 3;
  if (contact.linkedin_url) n += 2;
  if (contact.instagram_handle) n += 2;
  if (contact.phone) n += 1;
  if (contact.full_name) n += 2;
  return n;
}

/**
 * Pick the person to address in the DM.
 * @returns {{ contact, role, why, ranked, confidence }}
 */
function selectDecisionMaker(contacts = [], company = {}) {
  const small = isSmallBusiness(company);
  const priority = small ? PRIORITY_SMALL : PRIORITY_LARGE;

  const scored = contacts
    .filter((c) => c && (c.full_name || c.title))
    .map((c) => {
      const role = c.role_category && c.role_category !== 'unknown' ? c.role_category : classifyRole(c.title);
      const rank = priority.indexOf(role);
      return {
        ...c,
        role_category: role,
        _rank: rank === -1 ? priority.length + (role === 'other' ? 1 : 0) : rank,
        _completeness: contactCompleteness(c),
        _confidence: typeof c.source_confidence === 'number' ? c.source_confidence : 0.5
      };
    })
    .sort((a, b) =>
      a._rank - b._rank ||
      b._confidence - a._confidence ||
      b._completeness - a._completeness
    );

  if (!scored.length) {
    return {
      contact: null,
      role: null,
      why: 'No named person could be verified from public sources. Outreach will address the business account directly without using a name.',
      ranked: [],
      confidence: 0
    };
  }

  const chosen = scored[0];
  return {
    contact: chosen,
    role: chosen.role_category,
    why: explainChoice(chosen, company, small),
    ranked: scored.map((c) => ({ full_name: c.full_name, title: c.title, role_category: c.role_category, rank: c._rank })),
    confidence: Number((chosen._confidence * (chosen._rank < priority.length ? 1 : 0.6)).toFixed(2))
  };
}

function explainChoice(contact, company, small) {
  const name = contact.full_name ?? 'this contact';
  const title = contact.title ?? contact.role_category?.replace(/_/g, ' ');
  const size = company.employee_count
    ? `${company.employee_count} employees`
    : company.company_size ?? (small ? 'a small team' : 'a larger team');
  if (small && ['founder', 'owner', 'co_founder', 'ceo'].includes(contact.role_category)) {
    return `${name} is listed as ${title}. At ${size}, the founder/owner is normally the person who still answers the DMs and decides whether to hand that off.`;
  }
  if (['head_of_operations', 'cx_director', 'support_manager'].includes(contact.role_category)) {
    return `${name} is listed as ${title}. At ${size}, this is the person who owns the support queue and feels the volume directly.`;
  }
  if (contact.role_category === 'marketing_director') {
    return `${name} is listed as ${title}. No operations or support lead was found publicly, and marketing usually owns the social inbox where these inquiries land.`;
  }
  return `${name} (${title ?? 'role unclear'}) is the most senior contact that could be verified publicly for this business.`;
}

// ---- lib/normalize.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Normalisation primitives.
// Everything that turns messy scraped text into a comparable value lives here.
// Pure functions only - no I/O - so the same code runs in tests, in n8n Code
// nodes (inlined by n8n/build.mjs) and in scripts.
// ---------------------------------------------------------------------------

const US_STATES = {
  alabama: 'AL', alaska: 'AK', arizona: 'AZ', arkansas: 'AR', california: 'CA',
  colorado: 'CO', connecticut: 'CT', delaware: 'DE', 'district of columbia': 'DC',
  florida: 'FL', georgia: 'GA', hawaii: 'HI', idaho: 'ID', illinois: 'IL',
  indiana: 'IN', iowa: 'IA', kansas: 'KS', kentucky: 'KY', louisiana: 'LA',
  maine: 'ME', maryland: 'MD', massachusetts: 'MA', michigan: 'MI', minnesota: 'MN',
  mississippi: 'MS', missouri: 'MO', montana: 'MT', nebraska: 'NE', nevada: 'NV',
  'new hampshire': 'NH', 'new jersey': 'NJ', 'new mexico': 'NM', 'new york': 'NY',
  'north carolina': 'NC', 'north dakota': 'ND', ohio: 'OH', oklahoma: 'OK',
  oregon: 'OR', pennsylvania: 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
  'south dakota': 'SD', tennessee: 'TN', texas: 'TX', utah: 'UT', vermont: 'VT',
  virginia: 'VA', washington: 'WA', 'west virginia': 'WV', wisconsin: 'WI',
  wyoming: 'WY'
};

const STATE_CODES = new Set(Object.values(US_STATES));

// Legal-entity and decorative suffixes that must not make two rows look different.
const NAME_NOISE = [
  'llc', 'l l c', 'inc', 'inc.', 'incorporated', 'corp', 'corporation', 'co',
  'company', 'ltd', 'limited', 'plc', 'pllc', 'pc', 'pa', 'dds', 'md', 'dmd',
  'the', 'official', 'shop', 'store', 'usa', 'us'
];

function stripDiacritics(value) {
  return String(value ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function collapseWhitespace(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** Display-safe business name: trimmed, de-emojied, single-spaced. */
function cleanBusinessName(value) {
  if (!value) return null;
  const cleaned = collapseWhitespace(
    stripDiacritics(value)
      .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
      .replace(/[|•·–—]+/g, ' ')
  );
  return cleaned || null;
}

/**
 * Comparison key for a business name. Lowercase, no punctuation, no legal
 * suffixes, no filler words. "Glow Med Spa, LLC" and "glow medspa" collapse to
 * the same key, which is what the dedupe layer matches on.
 */
function normalizeBusinessName(value) {
  const base = cleanBusinessName(value);
  if (!base) return null;
  const tokens = base
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter((t) => !NAME_NOISE.includes(t));
  // "med spa" -> "medspa", "hair salon" -> "hairsalon" is too aggressive; only
  // collapse the two-token forms that are genuinely written both ways.
  const joined = tokens.join(' ')
    .replace(/\bmed spa\b/g, 'medspa')
    .replace(/\bday spa\b/g, 'dayspa')
    .replace(/\be commerce\b/g, 'ecommerce');
  return joined || null;
}

/** Instagram handle without @, url wrapper, query string or trailing slash. */
function normalizeHandle(value) {
  if (!value) return null;
  let handle = String(value).trim();
  const urlMatch = handle.match(/instagram\.com\/([^/?#]+)/i);
  if (urlMatch) handle = urlMatch[1];
  handle = handle.replace(/^@+/, '').replace(/\/+$/, '').split('?')[0].trim().toLowerCase();
  if (!handle) return null;
  // Instagram handles: letters, numbers, periods, underscores, max 30 chars.
  if (!/^[a-z0-9._]{1,30}$/.test(handle)) return null;
  const reserved = new Set(['p', 'reel', 'reels', 'explore', 'stories', 'accounts', 'direct', 'tv']);
  if (reserved.has(handle)) return null;
  return handle;
}

function instagramUrl(handle) {
  const h = normalizeHandle(handle);
  return h ? `https://www.instagram.com/${h}/` : null;
}

/** Absolute, lowercase-host URL with tracking parameters removed. */
function normalizeUrl(value) {
  if (!value) return null;
  let raw = String(value).trim();
  if (!raw || raw === '-' || raw.toLowerCase() === 'n/a') return null;
  if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;
  let url;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(url.hostname)) return null;
  for (const key of [...url.searchParams.keys()]) {
    if (/^(utm_|fbclid|gclid|mc_|ref|source)/i.test(key)) url.searchParams.delete(key);
  }
  url.hostname = url.hostname.toLowerCase();
  url.hash = '';
  const path = url.pathname.replace(/\/+$/, '');
  return `${url.protocol}//${url.hostname}${path}${url.search}`;
}

// Link-in-bio aggregators are not a website - they must never become a dedupe key.
const AGGREGATOR_DOMAINS = new Set([
  'linktr.ee', 'link.tree', 'beacons.ai', 'bio.link', 'linkin.bio', 'msha.ke',
  'taplink.cc', 'lnk.bio', 'solo.to', 'campsite.bio', 'linkpop.com', 'many.link',
  'instagram.com', 'facebook.com', 'm.facebook.com', 'business.facebook.com',
  'tiktok.com', 'youtube.com', 'twitter.com', 'x.com', 'wa.me', 'api.whatsapp.com',
  'g.page', 'goo.gl', 'maps.google.com', 'yelp.com', 'booksy.com', 'vagaro.com',
  'square.site', 'squareup.com', 'calendly.com', 'sites.google.com'
]);

function isAggregatorDomain(domain) {
  if (!domain) return false;
  const d = String(domain).toLowerCase().replace(/^www\./, '');
  return AGGREGATOR_DOMAINS.has(d);
}

/** Registrable-ish domain: host without www, aggregators rejected. */
function normalizeDomain(value) {
  const url = normalizeUrl(value);
  if (!url) return null;
  let host;
  try {
    host = new URL(url).hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return null;
  }
  if (isAggregatorDomain(host)) return null;
  return host;
}

/** US phone to E.164. Anything that is not a plausible US number returns null. */
function normalizePhone(value, defaultCountry = '1') {
  if (!value) return null;
  const raw = String(value);
  if (/ext|x\d{3,}/i.test(raw) === false && raw.trim().startsWith('+')) {
    const intl = raw.replace(/[^\d+]/g, '');
    if (/^\+\d{8,15}$/.test(intl)) return intl;
  }
  const digits = raw.replace(/\D/g, '');
  if (!digits) return null;
  let national = digits;
  if (national.length === 11 && national.startsWith('1')) national = national.slice(1);
  if (national.length !== 10) return null;
  if (/^[01]/.test(national)) return null;              // invalid NANP area code
  if (/^(\d)\1{9}$/.test(national)) return null;        // 5555555555 style junk
  return `+${defaultCountry}${national}`;
}

function normalizeEmail(value) {
  if (!value) return null;
  const email = String(value).trim().toLowerCase().replace(/^mailto:/, '');
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(email)) return null;
  const local = email.split('@')[0];
  if (/^(noreply|no-reply|donotreply|postmaster|abuse|privacy)$/.test(local)) return null;
  return email;
}

/** Accepts "California", "california", "CA", "Calif." -> "CA". */
function normalizeState(value) {
  if (!value) return null;
  const raw = String(value).trim();
  const upper = raw.toUpperCase();
  if (STATE_CODES.has(upper)) return upper;
  const key = stripDiacritics(raw).toLowerCase().replace(/[^a-z\s]/g, '').trim();
  if (US_STATES[key]) return US_STATES[key];
  const prefix = Object.keys(US_STATES).find((name) => name.startsWith(key) && key.length >= 4);
  return prefix ? US_STATES[prefix] : null;
}

function normalizeCity(value) {
  if (!value) return null;
  const city = collapseWhitespace(stripDiacritics(value).replace(/[^\p{L}\s.'-]/gu, ' '));
  if (!city || city.length < 2) return null;
  return city
    .toLowerCase()
    .split(' ')
    .map((w) => (w.length > 2 || /^(st|ft)$/.test(w) ? w[0].toUpperCase() + w.slice(1) : w))
    .join(' ');
}

function slug(value) {
  return stripDiacritics(String(value ?? ''))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '')
    .slice(0, 40);
}

/** "12.3k" / "1,234" / "2.1M" -> integer. */
function parseCount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? Math.round(value) : null;
  const raw = String(value).trim().toLowerCase().replace(/,/g, '').replace(/\s/g, '');
  const match = raw.match(/^([\d.]+)([km])?$/);
  if (!match) return null;
  const n = Number.parseFloat(match[1]);
  if (!Number.isFinite(n)) return null;
  const mult = match[2] === 'k' ? 1e3 : match[2] === 'm' ? 1e6 : 1;
  return Math.round(n * mult);
}

function toIsoDate(value) {
  if (!value) return null;
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function daysSince(value, now = new Date()) {
  const iso = toIsoDate(value);
  if (!iso) return null;
  return Math.floor((now.getTime() - new Date(iso).getTime()) / 86400000);
}

/**
 * Normalise a raw discovery row into the canonical lead shape every downstream
 * step expects. Unknown provider fields are kept under `raw`.
 */
function normalizeRawLead(raw = {}) {
  const pick = (...keys) => {
    for (const k of keys) {
      const v = k.split('.').reduce((o, part) => (o == null ? o : o[part]), raw);
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return null;
  };

  const name = cleanBusinessName(pick('business_name', 'name', 'title', 'fullName', 'ownerFullName'));
  const handle = normalizeHandle(pick('instagram_handle', 'username', 'instagram', 'instagramUrl', 'instagram_url'));
  const website = normalizeUrl(pick('website', 'url', 'externalUrl', 'external_url', 'site'));
  const domain = normalizeDomain(website);
  const state = normalizeState(pick('state', 'region', 'administrativeArea', 'address.state'));
  const city = normalizeCity(pick('city', 'locality', 'address.city'));
  const products = toProductList(pick('products_services', 'products', 'services', 'menu', 'categories'));

  return {
    business_name: name,
    name_normalized: normalizeBusinessName(name),
    instagram_handle: handle,
    instagram_url: instagramUrl(handle) ?? normalizeUrl(pick('instagram_url', 'instagramUrl')),
    website,
    website_domain: domain,
    email: normalizeEmail(pick('email', 'emails.0', 'contact_email')),
    phone: pick('phone', 'phoneNumber', 'phone_number', 'telephone'),
    phone_e164: normalizePhone(pick('phone', 'phoneNumber', 'phone_number', 'telephone')),
    country: pick('country', 'countryCode') ?? 'US',
    state,
    city,
    postal_code: pick('postal_code', 'postalCode', 'zip'),
    address: pick('address', 'formattedAddress', 'street'),
    latitude: numberOrNull(pick('latitude', 'location.lat', 'lat')),
    longitude: numberOrNull(pick('longitude', 'location.lng', 'lng')),
    category: pick('category', 'categoryName', 'businessCategoryName', 'business_category'),
    bio: pick('bio', 'biography', 'description'),
    website_description: pick('website_description', 'meta_description'),
    products_services: products,
    products_count: products.length || parseCount(pick('products_count', 'productsCount')),
    ig_followers: parseCount(pick('ig_followers', 'followersCount', 'followers', 'follower_count')),
    ig_following: parseCount(pick('ig_following', 'followsCount', 'following')),
    ig_posts: parseCount(pick('ig_posts', 'postsCount', 'posts', 'media_count')),
    ig_is_business: boolOrNull(pick('ig_is_business', 'isBusinessAccount', 'is_business_account')),
    ig_is_private: boolOrNull(pick('ig_is_private', 'private', 'is_private')),
    ig_is_verified: boolOrNull(pick('ig_is_verified', 'verified', 'is_verified')),
    ig_last_post_at: toIsoDate(pick('ig_last_post_at', 'latestPostDate', 'last_post_at')),
    ig_external_url: normalizeUrl(pick('externalUrl', 'external_url', 'bio_link')),
    place_id: pick('place_id', 'placeId', 'fid'),
    source: pick('source', '_source') ?? 'unknown',
    source_search_term: pick('search_term', 'searchString', 'query'),
    raw
  };
}

function numberOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function boolOrNull(v) {
  if (v === true || v === false) return v;
  if (v === 'true') return true;
  if (v === 'false') return false;
  return null;
}

/** Products/services arrive as arrays, comma strings or objects. */
function toProductList(value) {
  if (!value) return [];
  let items = [];
  if (Array.isArray(value)) items = value;
  else if (typeof value === 'string') items = value.split(/[,;|\n]/);
  else if (typeof value === 'object') items = Object.values(value);
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const label = collapseWhitespace(
      typeof item === 'string' ? item : (item?.name ?? item?.title ?? item?.label ?? '')
    );
    if (!label || label.length < 2 || label.length > 120) continue;
    const key = label.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(label);
  }
  return out;
}

// ---- node logic ----
const prepared = $('Prepare Enrichment Input').all().map((i) => i.json);
const out = [];

function fromApollo(payload) {
  const people = payload?.people ?? payload?.contacts ?? [];
  return people.map((p) => ({
    full_name: p.name ?? ([p.first_name, p.last_name].filter(Boolean).join(' ') || null),
    first_name: p.first_name ?? null,
    last_name: p.last_name ?? null,
    title: p.title ?? null,
    role_category: classifyRole(p.title),
    seniority: p.seniority ?? null,
    email: p.email && !/email_not_unlocked/i.test(p.email) ? normalizeEmail(p.email) : null,
    phone: p.phone_numbers?.[0]?.sanitized_number ?? null,
    linkedin_url: p.linkedin_url ?? null,
    source: 'apollo',
    source_confidence: p.email ? 0.9 : 0.7
  })).filter((c) => c.full_name || c.title);
}

function fromHtml(html) {
  if (typeof html !== 'string') return [];
  const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  const found = [];
  const re = /([A-Z][a-z]+(?:\s+[A-Z][a-z]+){1,2})\s*[,|\-\u2013]\s*((?:founder|co-?founder|owner|ceo|president|director|head of [a-z ]+|manager)[a-z ]*)/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    found.push({
      full_name: m[1].trim(), first_name: m[1].trim().split(' ')[0], title: m[2].trim(),
      role_category: classifyRole(m[2]), source: 'website_scrape', source_confidence: 0.55
    });
  }
  return found;
}

for (const [index, item] of $input.all().entries()) {
  const context = prepared[index] ?? prepared[0] ?? {};
  const payload = item.json;
  const contacts = [...fromApollo(payload), ...fromHtml(payload?.data ?? payload?.body ?? payload)];

  const company = {
    employee_count: payload?.people?.[0]?.organization?.estimated_num_employees ?? null,
    company_size: null,
    business_model: $('Load Campaign + Niche').first().json.niche?.business_model ?? null
  };

  const chosen = selectDecisionMaker(contacts, company);

  out.push({ json: {
    lead_id: context.lead_id,
    company_id: context.company_id,
    campaign_id: context.campaign_id,
    contacts,
    contacts_found: contacts.length,
    employee_count: company.employee_count,
    decision_maker: chosen.contact,
    decision_maker_reason: chosen.why,
    decision_maker_confidence: chosen.confidence,
    // A lead with no contact is NOT dropped - it continues with what is known.
    keep_without_contact: true
  } });
}
return out;

